// Mirror return-based teamMode changes from project source to marketplace + cache 0.6.14.
const fs = require('fs');
const path = require('path');
const SRC = 'C:/Users/pssps/Documents/Projects/sc4sap_project/sc4sap';
const MKT = 'C:/Users/pssps/.claude/plugins/marketplaces/sc4sap';
const CACHE = 'C:/Users/pssps/.claude/plugins/cache/sc4sap/sc4sap/0.6.14';

const copyAll = [
  'common/team-consultation-protocol.md',
  'skills/ask-consultant/team-mode.md',
  'skills/ask-consultant/team-rounds.md',
  'skills/compare-programs/team-mode.md',
  'skills/create-program/team-mode.md',
  'skills/create-program/team-mode-b.md',
  'skills/create-program/team-mode-d.md',
  'skills/analyze-code/team-mode.md',
];
const docs = [
  'docs/team-consultation-architecture.md',
  'docs/team-consultation-architecture.ko.md',
];
const patches = {
  'skills/ask-consultant/SKILL.md': [
    '(adds `team_name`, `name`, charter-file reference; consultants write POSITION files instead of returning directly).',
    '(inlined charter + `teamMode=true`; each consultant returns a POSITION block ahead of its answer and the lead persists it to the run directory — no `team_name`).',
  ],
  'skills/compare-programs/workflow.md': [
    '(adds `team_name`, `name`, charter-file reference)',
    '(inlined charter + `teamMode=true`; consultants return POSITION blocks that the lead persists — no `team_name`)',
  ],
  'common/model-dispatch-mode.md': [
    '- Team mode (`team_name` teammates) follows the same rule: one question per spawn group before the teammates are created.',
    "- Team mode (teamMode rounds per `team-consultation-protocol.md`) follows the same rule: each round's parallel member dispatch is one group → one question before that round is dispatched.",
  ],
};

function copy(root, rel) {
  fs.copyFileSync(path.join(SRC, rel), path.join(root, rel));
  console.log(`  copied  ${rel}`);
}
function patch(root, rel) {
  const p = path.join(root, rel);
  if (!fs.existsSync(p)) { console.log(`  skip    ${rel} (absent)`); return; }
  const [a, b] = patches[rel];
  const s = fs.readFileSync(p, 'utf8');
  if (s.includes(b)) { console.log(`  ok      ${rel} (already patched)`); return; }
  if (!s.includes(a)) { console.log(`  MISS    ${rel} (anchor not found)`); return; }
  fs.writeFileSync(p, s.replace(a, b));
  console.log(`  patched ${rel}`);
}

for (const [label, root, withDocs] of [['marketplace', MKT, true], ['cache 0.6.14', CACHE, false]]) {
  console.log(`== ${label}`);
  copyAll.forEach((r) => copy(root, r));
  if (withDocs) docs.forEach((r) => copy(root, r));
  Object.keys(patches).forEach((r) => patch(root, r));
}

