// Replace hardcoded model versions with tier names / aliases across plugin markdown.
const fs = require('fs');
const path = require('path');
const ROOT = 'C:/Users/pssps/Documents/Projects/sc4sap_project/sc4sap';
const SKIP_DIRS = new Set(['vendor', 'node_modules', '.sc4sap', '.git', 'program-to-spec']);
const SKIP_FILES = new Set(['CHANGELOG.md']);
const DRY = process.argv.includes('--dry');

const files = [];
(function walk(dir) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    if (e.isDirectory()) { if (!SKIP_DIRS.has(e.name)) walk(path.join(dir, e.name)); }
    else if (e.name.endsWith('.md') && !SKIP_FILES.has(e.name)) files.push(path.join(dir, e.name));
  }
})(ROOT);

const frontmatter = [
  [/^model: claude-opus-4-7$/m, 'model: opus'],
  [/^model: claude-sonnet-4-6$/m, 'model: sonnet'],
  [/^model: claude-haiku-4-5$/m, 'model: haiku'],
];
const text = [
  [/Opus 4\.7/g, 'Opus'],
  [/Sonnet 4\.6/g, 'Sonnet'],
  [/Haiku 4\.5/g, 'Haiku'],
];

let total = 0;
for (const f of files) {
  const raw = fs.readFileSync(f, 'utf8');
  const crlf = raw.includes('\r\n');
  let s = raw.replace(/\r\n/g, '\n');
  let n = 0;
  if (f.includes(`${path.sep}agents${path.sep}`) || f.includes('/agents/')) {
    for (const [re, to] of frontmatter) if (re.test(s)) { s = s.replace(re, to); n++; }
  }
  for (const [re, to] of text) { const m = s.match(re); if (m) { n += m.length; s = s.replace(re, to); } }
  if (!n) continue;
  total += n;
  console.log(`${String(n).padStart(3)}  ${path.relative(ROOT, f)}`);
  if (!DRY) fs.writeFileSync(f, crlf ? s.replace(/\n/g, '\r\n') : s);
}
console.log(`total replacements: ${total}${DRY ? ' (dry run)' : ''}`);

