// ask-consultant + setup: main thread follows the session model (model: inherit).
const fs = require('fs');
const path = require('path');
const root = process.argv[2];

const edits = {
  'skills/ask-consultant/SKILL.md': [
    ['model: haiku', 'model: inherit'],
    ['Per-step model allocation (skill frontmatter pins the main thread to Haiku; Agent dispatches carry their own model):',
     'Per-step model allocation (the main thread follows the session model — frontmatter `model: inherit`, because it judges divergence and reviews the synthesis; Agent dispatches carry their own model):'],
    ['(Haiku · skill-to-skill)', '(main · skill-to-skill)'],
    ['(Haiku · main thread)', '(main thread)'],
    ['main thread (Haiku) just forwards', 'main thread just forwards'],
    ['[Model: Haiku · Dispatched: Opus×1', '[Model: <main> · Dispatched: Opus×1'],
    ['[Model: Haiku · Dispatched: Opus×2 (sap-mm-consultant, sap-fi-consultant), Sonnet×1 (sap-writer synthesis)]',
     '[Model: <main> · Dispatched: Opus×2 (sap-mm-consultant, sap-fi-consultant), Sonnet×1 (sap-writer synthesis)]'],
    ['[Model: Haiku · Dispatched: Opus×2 (sap-mm-consultant, sap-fi-consultant), Sonnet×1 (sap-writer team-synthesis)',
     '[Model: <main> · Dispatched: Opus×2 (sap-mm-consultant, sap-fi-consultant), Sonnet×1 (sap-writer team-synthesis)'],
  ],
  'skills/ask-consultant/team-mode.md': [
    ['Replaces the Haiku main / Sonnet writer path of `SKILL.md` Step 5.', 'Replaces the legacy writer path of `SKILL.md` Step 5.'],
  ],
  'skills/setup/SKILL.md': [
    ['model: haiku', 'model: inherit'],
    ["Setup's happy path runs entirely on the main thread (Haiku per frontmatter)", "Setup's happy path runs entirely on the main thread (session model — frontmatter `model: inherit`)"],
    ['the main thread (Haiku) surfaces it', 'the main thread surfaces it'],
  ],
  'docs/skill-model-architecture.md': [
    ['| `ask-consultant` | Haiku | Intake + keyword routing + output formatting |',
     '| `ask-consultant` | inherit | Routing, teamMode divergence checks and synthesis review need the session model |'],
    ['| `setup` | Haiku | Configuration workflow (Q&A + Bash CLI + template MCP) |',
     '| `setup` | inherit | Configuration workflow with failure triage; a Haiku main would misjudge escalation |'],
    ['#### `setup` — Haiku main, escalation-only dispatches', '#### `setup` — session-model main, escalation-only dispatches'],
    ['#### `ask-consultant` — Haiku main, 1–N+1 dispatches', '#### `ask-consultant` — session-model main, 1–N+1 dispatches'],
  ],
};

for (const [rel, pairs] of Object.entries(edits)) {
  const p = path.join(root, rel);
  if (!fs.existsSync(p)) { console.log('skip (absent)', rel); continue; }
  const raw = fs.readFileSync(p, 'utf8');
  const crlf = raw.includes('\r\n');
  let s = raw.replace(/\r\n/g, '\n');
  for (const [a, b] of pairs) {
    if (s.includes(b) && !s.includes(a)) continue;
    if (!s.includes(a)) { console.log('MISS', rel, '::', a.slice(0, 60)); continue; }
    s = s.split(a).join(b);
  }
  fs.writeFileSync(p, crlf ? s.replace(/\n/g, '\r\n') : s);
  console.log('ok', rel);
}

